//! Cross-checks against the Python reference stack (smbprotocol + pyspnego).
//!
//! `reference_vectors.rs` is generated by `tests/reference/gen_vectors.py`
//! with every random input pinned; the tests below feed the same inputs to
//! the Rust codec and require identical bytes (or, for structures the Python
//! side only encodes, identical decoded fields).

use bytes::Bytes;

use crate::auth::ntlm::{FixedInputs, NtlmVersion};
use crate::auth::spnego::{NegState, NegotiationToken};
use crate::auth::{AuthStep, Authenticator, NtlmClient, NtlmConfig, NtlmCredentials, SpnegoClient};
use crate::crypto::{
    Cipher, PreauthHasher, Signer, SigningAlgorithm, SmbCipher, derive_session_keys,
};
use crate::fscc::*;
use crate::header::{Command, HEADER_LEN, Header, HeaderFlags};
use crate::msg::*;
use crate::reference_vectors::*;
use crate::status::NtStatus;
use crate::types::{Capabilities, Dialect, FileId, SecurityMode};
use crate::wire::Guid;

fn h(s: &str) -> Vec<u8> {
    hex::decode(s).expect("valid hex in reference vectors")
}

const SERVER_TIME: u64 = 133_500_000_000_000_000;
const FILE_ID: FileId = FileId::new(0x0102_0304_0506_0708, 0x1112_1314_1516_1718);

fn guid(start: u8) -> Guid {
    let mut g = [0u8; 16];
    for (i, b) in g.iter_mut().enumerate() {
        *b = start + i as u8;
    }
    Guid(g)
}

fn range(start: u8, n: usize) -> Vec<u8> {
    (0..n).map(|i| start.wrapping_add(i as u8)).collect()
}

fn ntlm_client() -> NtlmClient {
    let cfg = NtlmConfig {
        version: Some(NtlmVersion {
            major: 10,
            minor: 0,
            build: 19041,
            revision: 15,
        }),
        workstation: Some("FSFAST-WS".into()),
        target_spn: Some("cifs/server.domain.test".into()),
        ..Default::default()
    };
    let mut c = NtlmClient::with_config(NtlmCredentials::new("DOMAIN\\User", "Password"), cfg);
    c.set_fixed_inputs(FixedInputs {
        client_challenge: [0xAA; 8],
        exported_session_key: [0x55; 16],
        time: None,
    });
    c
}

#[test]
fn ntlm_messages_match_pyspnego() {
    let mut c = ntlm_client();
    let AuthStep::Continue(neg) = c.step(&[]).unwrap() else {
        panic!("expected NEGOTIATE")
    };
    assert_eq!(hex::encode(&neg), NTLM_NEGOTIATE);
    let AuthStep::Done(Some(auth)) = c.step(&h(NTLM_CHALLENGE)).unwrap() else {
        panic!("expected AUTHENTICATE")
    };
    assert_eq!(hex::encode(&auth), NTLM_AUTHENTICATE);
    assert_eq!(hex::encode(c.session_key().unwrap()), NTLM_SESSION_KEY);
    assert!(c.mic_provided());
}

#[test]
fn spnego_tokens_match_pyspnego() {
    let mut s = SpnegoClient::new(vec![Box::new(ntlm_client())]).unwrap();
    let AuthStep::Continue(init) = s.step(&[]).unwrap() else {
        panic!()
    };
    assert_eq!(hex::encode(&init), SPNEGO_INIT);
    let AuthStep::Continue(auth) = s.step(&h(SPNEGO_CHALLENGE)).unwrap() else {
        panic!()
    };
    let NegotiationToken::Resp(ours) = NegotiationToken::decode(&auth).unwrap() else {
        panic!()
    };
    let NegotiationToken::Resp(theirs) = NegotiationToken::decode(&h(SPNEGO_AUTH)).unwrap() else {
        panic!()
    };
    // pyspnego adds negState accept-incomplete to the initiator's token;
    // Samba and Windows clients omit it. Everything else is identical.
    assert_eq!(theirs.neg_state, Some(NegState::AcceptIncomplete));
    assert_eq!(ours.neg_state, None);
    assert_eq!(ours.supported_mech, theirs.supported_mech);
    assert_eq!(
        ours.response_token, theirs.response_token,
        "AUTHENTICATE inside SPNEGO"
    );
    assert_eq!(ours.mech_list_mic, theirs.mech_list_mic, "mechListMIC");
    assert_eq!(s.step(&h(SPNEGO_FINAL)).unwrap(), AuthStep::Done(None));
    assert!(s.is_complete() && s.mech_list_mic_verified());
    assert_eq!(hex::encode(s.session_key().unwrap()), SPNEGO_SESSION_KEY);
}

#[test]
fn key_derivation_matches_smbprotocol() {
    let k = derive_session_keys(
        Dialect::SMB_3_0_2,
        &h(KDF_SESSION_KEY_16),
        None,
        Some(Cipher::Aes128Ccm),
    )
    .unwrap();
    assert_eq!(hex::encode(*k.signing_key), KEYS_302_SIGNING);
    assert_eq!(hex::encode(*k.application_key), KEYS_302_APP);
    assert_eq!(
        hex::encode(k.encryption_key.as_ref().unwrap().as_slice()),
        KEYS_302_ENC
    );
    assert_eq!(
        hex::encode(k.decryption_key.as_ref().unwrap().as_slice()),
        KEYS_302_DEC
    );

    let preauth: [u8; 64] = h(KDF_PREAUTH).try_into().unwrap();
    let full = h(KDF_SESSION_KEY_32);
    let k = derive_session_keys(
        Dialect::SMB_3_1_1,
        &full,
        Some(&preauth),
        Some(Cipher::Aes128Gcm),
    )
    .unwrap();
    assert_eq!(hex::encode(*k.signing_key), KEYS_311_SIGNING);
    assert_eq!(hex::encode(*k.application_key), KEYS_311_APP);
    assert_eq!(
        hex::encode(k.encryption_key.as_ref().unwrap().as_slice()),
        KEYS_311_ENC128
    );
    assert_eq!(
        hex::encode(k.decryption_key.as_ref().unwrap().as_slice()),
        KEYS_311_DEC128
    );
    for c in [Cipher::Aes256Gcm, Cipher::Aes256Ccm] {
        let k = derive_session_keys(Dialect::SMB_3_1_1, &full, Some(&preauth), Some(c)).unwrap();
        assert_eq!(hex::encode(*k.signing_key), KEYS_311_SIGNING);
        assert_eq!(
            hex::encode(k.encryption_key.as_ref().unwrap().as_slice()),
            KEYS_311_ENC256
        );
        assert_eq!(
            hex::encode(k.decryption_key.as_ref().unwrap().as_slice()),
            KEYS_311_DEC256
        );
    }

    let mut p = PreauthHasher::new();
    for m in [
        &b"negotiate request"[..],
        b"negotiate response",
        b"session setup request",
    ] {
        p.update(m);
    }
    assert_eq!(hex::encode(p.value()), PREAUTH_CHAIN);
}

#[test]
fn signatures_match_smbprotocol() {
    let key = h(SIGN_KEY);
    let msg = h(SIGN_MESSAGE);
    for (alg, expected) in [
        (SigningAlgorithm::HmacSha256, SIGN_HMAC),
        (SigningAlgorithm::AesCmac, SIGN_CMAC),
        (SigningAlgorithm::AesGmac, SIGN_GMAC),
    ] {
        let s = Signer::new(alg, &key).unwrap();
        assert_eq!(
            hex::encode(s.compute(&[&msg]).unwrap()),
            expected,
            "{alg:?}"
        );
        // Signing in place writes the same signature into the header and
        // verification accepts it; split input gives the same result.
        let mut m = msg.clone();
        s.sign_in_place(&mut m).unwrap();
        assert_eq!(hex::encode(&m[48..64]), expected);
        s.verify(&m).unwrap();
        assert_eq!(
            hex::encode(s.compute(&[&msg[..70], &msg[70..]]).unwrap()),
            expected
        );
    }
    let gmac = Signer::new(SigningAlgorithm::AesGmac, &key).unwrap();
    assert_eq!(
        hex::encode(gmac.compute(&[&h(SIGN_GMAC_RESPONSE_MESSAGE)]).unwrap()),
        SIGN_GMAC_RESPONSE
    );
    assert_eq!(
        hex::encode(gmac.compute(&[&h(SIGN_GMAC_CANCEL_MESSAGE)]).unwrap()),
        SIGN_GMAC_CANCEL
    );
}

#[test]
fn encryption_matches_smbprotocol() {
    let plain = h(ENC_PLAINTEXT);
    let nonce_src = h(ENC_NONCE);
    let session_id = 0x0000_1000_0000_0005;
    for (cipher, key, expected) in [
        (Cipher::Aes128Ccm, ENC_KEY16, ENC_AES128CCM_30),
        (Cipher::Aes128Ccm, ENC_KEY16, ENC_AES128CCM),
        (Cipher::Aes128Gcm, ENC_KEY16, ENC_AES128GCM),
        (Cipher::Aes256Ccm, ENC_KEY32, ENC_AES256CCM),
        (Cipher::Aes256Gcm, ENC_KEY32, ENC_AES256GCM),
    ] {
        let c = SmbCipher::new(cipher, &h(key)).unwrap();
        let mut nonce = [0u8; 16];
        nonce[..cipher.nonce_len()].copy_from_slice(&nonce_src[..cipher.nonce_len()]);
        let frame = c
            .encrypt_with_nonce(session_id, &nonce, &[&plain[..20], &plain[20..]])
            .unwrap();
        assert_eq!(hex::encode(&frame), expected, "{cipher:?}");
        // And the Python frame decrypts with our code, in place and into a
        // caller buffer.
        let theirs = h(expected);
        let (hdr, p) = c
            .decrypt_in_place(bytes::BytesMut::from(&theirs[..]))
            .unwrap();
        assert_eq!(hdr.session_id, session_id);
        assert_eq!(&p[..], &plain[..]);
        let mut out = vec![0u8; plain.len()];
        let (_, n) = c.decrypt_into(&theirs, &mut out).unwrap();
        assert_eq!(&out[..n], &plain[..]);
        let (mut head, mut rest) = (vec![0u8; 64], vec![0u8; plain.len() - 64]);
        c.decrypt_into_parts(&theirs, &mut [&mut head, &mut rest])
            .unwrap();
        assert_eq!([head, rest].concat(), plain);
    }
}

/// The body bytes (after the 64-byte header) of an encoded message.
fn body<M: Message>(m: &M) -> Vec<u8> {
    let mut hdr = Header::request(M::COMMAND);
    if M::RESPONSE {
        hdr.flags = HeaderFlags::SERVER_TO_REDIR;
    }
    encode_message(&hdr, m).unwrap().into_contiguous()[HEADER_LEN..].to_vec()
}

/// A complete message made of a default header and `body`.
fn message(cmd: Command, response: bool, status: NtStatus, body: &[u8]) -> RawMessage {
    let mut hdr = Header::request(cmd);
    hdr.status = status;
    if response {
        hdr.flags = HeaderFlags::SERVER_TO_REDIR;
    }
    let mut b = hdr.to_bytes().to_vec();
    b.extend_from_slice(body);
    RawMessage::parse(Bytes::from(b)).unwrap()
}

fn decode<M: Message>(hex_body: &str) -> M {
    message(M::COMMAND, M::RESPONSE, NtStatus::SUCCESS, &h(hex_body))
        .decode::<M>()
        .unwrap()
}

#[test]
fn request_encodings_match_smbprotocol() {
    let neg = NegotiateRequest {
        security_mode: SecurityMode::SIGNING_ENABLED,
        capabilities: Capabilities::from_bits_retain(0x47),
        client_guid: guid(0),
        dialects: Dialect::ALL.to_vec(),
        negotiate_contexts: vec![
            NegotiateContext::PreauthIntegrity {
                hash_algorithms: vec![HashAlgorithm::SHA512],
                salt: Bytes::from(range(0, 32)),
            },
            NegotiateContext::Encryption {
                ciphers: vec![
                    CipherId::AES_128_GCM,
                    CipherId::AES_128_CCM,
                    CipherId::AES_256_GCM,
                    CipherId::AES_256_CCM,
                ],
            },
            NegotiateContext::NetName("server".into()),
            NegotiateContext::Signing {
                algorithms: vec![
                    SigningAlgorithmId::AES_GMAC,
                    SigningAlgorithmId::AES_CMAC,
                    SigningAlgorithmId::HMAC_SHA256,
                ],
            },
        ],
    };
    assert_eq!(hex::encode(body(&neg)), MSG_NEGOTIATE_REQ, "NEGOTIATE");
    assert_eq!(decode::<NegotiateRequest>(MSG_NEGOTIATE_REQ), neg);

    let mut token = vec![0x60, 0x10];
    token.extend(range(0, 16));
    let ss = SessionSetupRequest {
        security_mode: SecurityMode::SIGNING_ENABLED,
        capabilities: Capabilities::DFS,
        security_buffer: Bytes::from(token),
        ..Default::default()
    };
    assert_eq!(
        hex::encode(body(&ss)),
        MSG_SESSION_SETUP_REQ,
        "SESSION_SETUP"
    );

    let tc = TreeConnectRequest {
        path: "\\\\server\\share".into(),
        ..Default::default()
    };
    assert_eq!(hex::encode(body(&tc)), MSG_TREE_CONNECT_REQ, "TREE_CONNECT");

    let create = CreateRequest {
        requested_oplock_level: OplockLevel::LEASE,
        impersonation_level: ImpersonationLevel::IMPERSONATION,
        desired_access: AccessMask::from_bits_retain(0x0012_019F),
        file_attributes: FileAttributes::NORMAL,
        share_access: ShareAccess::all(), // READ | WRITE | DELETE
        create_disposition: CreateDisposition::OPEN_IF,
        create_options: CreateOptions::NON_DIRECTORY_FILE,
        name: "dir\\file.txt".into(),
        contexts: vec![
            CreateRequestContext::QueryMaximalAccess {
                timestamp: Some(FileTime(SERVER_TIME)),
            },
            CreateRequestContext::RequestLease(Lease::V2 {
                key: range(0x80, 16).try_into().unwrap(),
                state: LeaseState::from_bits_retain(7),
                flags: 4,
                duration: 0,
                parent_key: range(0x90, 16).try_into().unwrap(),
                epoch: 3,
            }),
            CreateRequestContext::DurableHandleRequestV2 {
                timeout: 60_000,
                flags: 0,
                create_guid: guid(0x50),
            },
            CreateRequestContext::AllocationSize(1 << 20),
        ],
        ..Default::default()
    };
    assert_eq!(hex::encode(body(&create)), MSG_CREATE_REQ, "CREATE");
    assert_eq!(decode::<CreateRequest>(MSG_CREATE_REQ), create);

    let close = CloseRequest {
        flags: CloseFlags::POSTQUERY_ATTRIB,
        file_id: FILE_ID,
    };
    assert_eq!(hex::encode(body(&close)), MSG_CLOSE_REQ, "CLOSE");

    let read = ReadRequest {
        length: 65536,
        offset: 4096,
        file_id: FILE_ID,
        minimum_count: 1,
        ..Default::default()
    };
    assert_eq!(hex::encode(body(&read)), MSG_READ_REQ, "READ");

    let write = WriteRequest {
        offset: 8192,
        file_id: FILE_ID,
        data: Bytes::from_static(b"hello world"),
        ..Default::default()
    };
    assert_eq!(hex::encode(body(&write)), MSG_WRITE_REQ, "WRITE");
    assert_eq!(decode::<WriteRequest>(MSG_WRITE_REQ), write);

    let qd = QueryDirectoryRequest {
        file_information_class: FileInfoClass::ID_BOTH_DIRECTORY,
        flags: QueryDirectoryFlags::RESTART_SCANS,
        file_id: FILE_ID,
        file_name: "*".into(),
        output_buffer_length: 65536,
        ..Default::default()
    };
    assert_eq!(
        hex::encode(body(&qd)),
        MSG_QUERY_DIRECTORY_REQ,
        "QUERY_DIRECTORY"
    );

    let qi = QueryInfoRequest::for_class::<FileAllInformation>(FILE_ID, 4096);
    assert_eq!(hex::encode(body(&qi)), MSG_QUERY_INFO_REQ, "QUERY_INFO");

    let rename = FileRenameInformation {
        replace_if_exists: true,
        root_directory: 0,
        file_name: "new\\name.txt".into(),
    };
    let set = SetInfoRequest::new(FILE_ID, &rename).unwrap();
    assert_eq!(
        hex::encode(body(&set)),
        MSG_SET_INFO_RENAME_REQ,
        "SET_INFO rename"
    );

    let vni = ValidateNegotiateInfoRequest {
        capabilities: Capabilities::from_bits_retain(0x47),
        guid: guid(0),
        security_mode: SecurityMode::SIGNING_ENABLED,
        dialects: vec![Dialect::SMB_3_0, Dialect::SMB_3_0_2],
    };
    let io = IoctlRequest::fsctl(
        fsctl::VALIDATE_NEGOTIATE_INFO,
        FileId::RELATED,
        vni.to_bytes().unwrap(),
        24,
    );
    let mut theirs = h(MSG_IOCTL_VNI_REQ);
    // smbprotocol points OutputOffset at the (empty) buffer; [MS-SMB2]
    // §2.2.31 says a client SHOULD send 0 without output data, as we do.
    assert_eq!(&theirs[36..40], &0x78u32.to_le_bytes());
    theirs[36..40].fill(0);
    assert_eq!(body(&io), theirs, "IOCTL VALIDATE_NEGOTIATE_INFO");

    let copy = SrvCopyChunkCopy {
        source_key: range(0, 24).try_into().unwrap(),
        chunks: vec![SrvCopyChunk {
            source_offset: 0,
            target_offset: 1 << 20,
            length: 1 << 20,
        }],
    };
    assert_eq!(
        hex::encode(copy.to_bytes().unwrap()),
        FSCTL_COPYCHUNK,
        "SRV_COPYCHUNK_COPY"
    );

    assert_eq!(
        hex::encode(body(&FlushRequest { file_id: FILE_ID })),
        MSG_FLUSH_REQ,
        "FLUSH"
    );
    assert_eq!(hex::encode(body(&EchoRequest)), MSG_ECHO_REQ);
    assert_eq!(hex::encode(body(&LogoffRequest)), MSG_LOGOFF_REQ);
    assert_eq!(
        hex::encode(body(&TreeDisconnectRequest)),
        MSG_TREE_DISCONNECT_REQ
    );
    assert_eq!(hex::encode(body(&CancelRequest)), MSG_CANCEL_REQ);

    let notify = ChangeNotifyRequest {
        flags: WATCH_TREE,
        output_buffer_length: 4096,
        file_id: FILE_ID,
        completion_filter: CompletionFilter::from_bits_retain(0x17),
    };
    assert_eq!(
        hex::encode(body(&notify)),
        MSG_CHANGE_NOTIFY_REQ,
        "CHANGE_NOTIFY"
    );

    let lock = LockRequest {
        lock_sequence: 0,
        file_id: FILE_ID,
        locks: vec![LockElement {
            offset: 0,
            length: 100,
            flags: LockFlags::from_bits_retain(0x12),
        }],
    };
    assert_eq!(hex::encode(body(&lock)), MSG_LOCK_REQ, "LOCK");
}

#[test]
fn responses_from_smbprotocol_decode() {
    let n: NegotiateResponse = decode(MSG_NEGOTIATE_RESP);
    assert_eq!(
        n.security_mode,
        SecurityMode::SIGNING_ENABLED | SecurityMode::SIGNING_REQUIRED
    );
    assert_eq!(n.dialect_revision, Dialect::SMB_3_1_1);
    assert_eq!(n.server_guid, guid(0x20));
    assert_eq!(n.capabilities.bits(), 0x2F);
    assert_eq!(
        (n.max_transact_size, n.max_read_size, n.max_write_size),
        (8 << 20, 8 << 20, 8 << 20)
    );
    assert_eq!(n.system_time, FileTime(SERVER_TIME));
    assert_eq!(&n.security_buffer[..], &h("600606042a030405")[..]);
    let (alg, salt) = n.preauth_integrity().unwrap();
    assert_eq!(
        (alg, &salt[..]),
        (HashAlgorithm::SHA512, &range(0x40, 32)[..])
    );
    assert_eq!(n.cipher(), Some(CipherId::AES_128_GCM));
    assert_eq!(n.signing_algorithm(), Some(SigningAlgorithmId::AES_GMAC));
    assert_eq!(
        hex::encode(body(&n)),
        MSG_NEGOTIATE_RESP,
        "NEGOTIATE response re-encodes identically"
    );

    let t: TreeConnectResponse = decode(MSG_TREE_CONNECT_RESP);
    assert_eq!(t.share_type, ShareType::DISK);
    assert!(
        t.share_flags
            .contains(ShareFlags::ENCRYPT_DATA | ShareFlags::NO_CACHING)
    );
    assert!(
        t.capabilities
            .contains(ShareCapabilities::CONTINUOUS_AVAILABILITY)
    );
    assert_eq!(t.maximal_access.bits(), 0x001F_01FF);
    assert_eq!(hex::encode(body(&t)), MSG_TREE_CONNECT_RESP);

    let c: CreateResponse = decode(MSG_CREATE_RESP);
    assert_eq!(c.oplock_level, OplockLevel::LEASE);
    assert_eq!(c.create_action, CreateAction::CREATED);
    assert_eq!(c.last_write_time, FileTime(SERVER_TIME + 20_000_000));
    assert_eq!((c.allocation_size, c.end_of_file), (4096, 11));
    assert_eq!(c.file_attributes, FileAttributes::ARCHIVE);
    assert_eq!(c.file_id, FILE_ID);
    assert_eq!(c.maximal_access().unwrap().bits(), 0x001F_01FF);
    assert!(c.contexts.contains(&CreateResponseContext::OnDiskId {
        disk_file_id: 0xABCD,
        volume_id: 0x1234
    }));
    assert!(
        c.contexts
            .contains(&CreateResponseContext::DurableHandleResponseV2 {
                timeout: 60_000,
                flags: 0
            })
    );
    let Lease::V2 {
        key, state, epoch, ..
    } = *c.lease().unwrap()
    else {
        panic!("lease v2")
    };
    assert_eq!((key.to_vec(), state.bits(), epoch), (range(0x80, 16), 3, 4));
    assert_eq!(
        hex::encode(body(&c)),
        MSG_CREATE_RESP,
        "CREATE response re-encodes identically"
    );

    let r: ReadResponse = decode(MSG_READ_RESP);
    assert_eq!(&r.data[..], b"hello world");

    let qd: QueryDirectoryResponse = decode(MSG_QUERY_DIRECTORY_RESP);
    let entries: Vec<DirEntry> = qd
        .entries(FileInfoClass::ID_BOTH_DIRECTORY)
        .unwrap()
        .collect::<crate::Result<_>>()
        .unwrap();
    assert_eq!(entries.len(), 2);
    assert_eq!(entries[0].file_name.to_string_lossy(), "a.txt");
    assert_eq!(
        (entries[0].end_of_file, entries[0].file_id),
        (100, Some(1000))
    );
    assert!(!entries[0].is_directory());
    assert_eq!(
        entries[1].file_name.to_string_lossy(),
        "longer-directory-name"
    );
    assert_eq!(
        entries[1].short_name.as_ref().unwrap().to_string_lossy(),
        "SHORT~1"
    );
    assert!(entries[1].is_directory());
    assert_eq!(
        entries[1].last_write_time,
        FileTime(SERVER_TIME + 20_000_000)
    );

    let qi: QueryInfoResponse = decode(MSG_QUERY_INFO_ALL_RESP);
    let all: FileAllInformation = qi.decode_as().unwrap();
    assert_eq!(all.basic.creation_time, FileTime(SERVER_TIME));
    assert_eq!(all.basic.file_attributes, FileAttributes::ARCHIVE);
    assert_eq!(
        (all.standard.end_of_file, all.standard.number_of_links),
        (11, 1)
    );
    assert_eq!(all.internal.index_number, 77);
    assert_eq!(all.access.access_flags.bits(), 0x001F_01FF);
    assert_eq!(all.mode.mode, 0x20);
    assert_eq!(all.name.file_name, "\\dir\\file.txt");

    let io: IoctlResponse = decode(MSG_IOCTL_VNI_RESP);
    let v = ValidateNegotiateInfoResponse::decode(&io.output).unwrap();
    assert_eq!(
        (v.capabilities.bits(), v.guid, v.dialect),
        (0x2F, guid(0x20), Dialect::SMB_3_0_2)
    );

    let ifs = decode_network_interfaces(&h(FSCTL_NETWORK_INTERFACES)).unwrap();
    assert_eq!(ifs.len(), 2);
    assert_eq!(ifs[0].ip(), Some("192.168.1.10".parse().unwrap()));
    assert_eq!(ifs[1].ip(), Some("fe80::1".parse().unwrap()));
    assert_eq!((ifs[0].if_index, ifs[1].link_speed), (1, 10_000_000_000));

    let err = message(
        Command::CREATE,
        true,
        NtStatus::STOPPED_ON_SYMLINK,
        &h(MSG_ERROR_SYMLINK_RESP),
    );
    assert!(err.is_error_response());
    let e = err.decode_error().unwrap();
    let sym = e.symlink().unwrap();
    assert_eq!(sym.substitute_name, "target\\dir");
    assert_eq!(sym.print_name, "\\??\\C:\\target\\dir");
    assert_eq!(sym.unparsed_path_length, 8);
    assert!(sym.is_relative());
}
